// 温度报警处理脚本
// 当温度超过阈值时执行

// 获取当前温度值
var temp1 = $getTag('TEMP_01');
var temp2 = $getTag('TEMP_02');
var temp3 = $getTag('TEMP_03');

// 计算平均温度
var avgTemp = (temp1 + temp2 + temp3) / 3;

// 记录日志
$log('温度报警触发 - 平均温度: ' + avgTemp.toFixed(1) + '°C');

// 如果平均温度超过120°C，自动降低电机转速
if (avgTemp > 120) {
    $log('温度过高，执行自动降温措施');

    // 检查电机是否运行
    if ($getTag('MOTOR_01_RUN')) {
        // 可以在这里添加降速逻辑
        $log('建议降低电机1转速');
    }
    if ($getTag('MOTOR_02_RUN')) {
        $log('建议降低电机2转速');
    }
}

// 发送通知（如果配置了）
// $notify('温度报警', '入口温度: ' + temp1 + '°C');

// 紧急停止处理脚本
// 当急停按钮按下时执行

$log('!!! 紧急停止触发 !!!');

// 立即停止所有电机
$setTag('MOTOR_01_CMD', false);
$setTag('MOTOR_02_CMD', false);

// 记录停止时间
var stopTime = new Date().toISOString();
$log('系统于 ' + stopTime + ' 紧急停止');

// 可以在这里添加其他安全措施
// 例如：关闭加热器、打开安全阀等

// 设置系统未就绪状态
$setTag('SYSTEM_READY', false);

// 显示警告消息
$toast('系统已紧急停止！请检查并排除故障后复位。', 'error');

// 生产计数脚本
// 每分钟执行一次，统计产量

// 获取当前计数
var currentCount = $getTag('PRODUCTION_COUNT') || 0;

// 根据电机运行状态估算产量
// 假设每个电机每分钟生产10件产品
var motor1Running = $getTag('MOTOR_01_RUN');
var motor2Running = $getTag('MOTOR_02_RUN');

var productionRate = 0;
if (motor1Running) productionRate += 10;
if (motor2Running) productionRate += 10;

// 更新计数
var newCount = currentCount + productionRate;
$setTag('PRODUCTION_COUNT', newCount);

// 计算设备效率
var maxRate = 20; // 最大产能
var efficiency = (productionRate / maxRate) * 100;
$setTag('EFFICIENCY', efficiency.toFixed(1));

// 记录日志
$log('生产计数更新: ' + newCount + '件，效率: ' + efficiency.toFixed(1) + '%');

// 启动前安全检查脚本

$log('执行启动前安全检查...');

var checks = {
    safetyDoor: $getTag('SAFETY_DOOR'),
    emergencyStop: $getTag('EMERGENCY_STOP'),
    temp1: $getTag('TEMP_01'),
    temp2: $getTag('TEMP_02'),
    temp3: $getTag('TEMP_03')
};

var canStart = true;
var messages = [];

// 检查安全门
if (!checks.safetyDoor) {
    canStart = false;
    messages.push('安全门未关闭');
}

// 检查急停
if (checks.emergencyStop) {
    canStart = false;
    messages.push('急停按钮被按下');
}

// 检查温度是否在正常范围
if (checks.temp1 > 100 || checks.temp2 > 140 || checks.temp3 > 110) {
    canStart = false;
    messages.push('温度过高，不能启动');
}

// 设置系统就绪状态
$setTag('SYSTEM_READY', canStart);

if (canStart) {
    $log('启动检查通过，系统就绪');
    $toast('系统就绪，可以启动', 'success');
} else {
    $log('启动检查失败: ' + messages.join(', '));
    $toast('启动失败: ' + messages.join(', '), 'error');
}

// 数据记录脚本
// 每5分钟记录一次关键数据

var data = {
    timestamp: new Date().toISOString(),
    temperature: {
        temp1: $getTag('TEMP_01'),
        temp2: $getTag('TEMP_02'),
        temp3: $getTag('TEMP_03'),
        avg: $getTag('TEMP_AVG'),
        max: $getTag('TEMP_MAX')
    },
    motors: {
        motor1: {
            running: $getTag('MOTOR_01_RUN'),
            rpm: $getTag('MOTOR_01_RPM')
        },
        motor2: {
            running: $getTag('MOTOR_02_RUN'),
            rpm: $getTag('MOTOR_02_RPM')
        }
    },
    production: {
        count: $getTag('PRODUCTION_COUNT'),
        efficiency: $getTag('EFFICIENCY')
    }
};

// 记录到历史数据库
$history('production_data', data);

$log('数据已记录到历史数据库: ' + data.timestamp);
